import{_ as e,o as a,c as l,a2 as i}from"./chunks/framework.ClgMjOt7.js";const u=JSON.parse('{"title":"Palleria の概要","description":"Palleria の概要、特徴、アーキテクチャ設計、および技術スタック","frontmatter":{"title":"Palleria の概要","description":"Palleria の概要、特徴、アーキテクチャ設計、および技術スタック"},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":1786168778000}'),r={name:"guide/index.md"};function o(n,t,s,d,c,h){return a(),l("div",null,[...t[0]||(t[0]=[i('<h1 id="palleria-の概要" tabindex="-1">Palleria の概要 <a class="header-anchor" href="#palleria-の概要" aria-label="Permalink to &quot;Palleria の概要&quot;">​</a></h1><p><strong>Palleria</strong> は Android 10（API レベル 29）以上を対象としたオープンソースの非公式 Pixiv クライアントアプリケーションです。</p><p>宣言型 UI フレームワークである <strong>Jetpack Compose</strong> と <strong>Miuix KMP</strong> コンポーネントシステムを採用し、通信およびデータ処理のネイティブコアとして <strong>Rust (UniFFI)</strong> を統合しています。</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Palleria は非公式の Pixiv クライアントであり、ピクシブ株式会社とは一切関係ありません。</p></div><hr><h2 id="採用技術スタック" tabindex="-1">採用技術スタック <a class="header-anchor" href="#採用技術スタック" aria-label="Permalink to &quot;採用技術スタック&quot;">​</a></h2><p>アプリ内で使用されている主要ライブラリおよび動作環境の一覧です。</p><h3 id="アプリケーション基盤" tabindex="-1">アプリケーション基盤 <a class="header-anchor" href="#アプリケーション基盤" aria-label="Permalink to &quot;アプリケーション基盤&quot;">​</a></h3><ul><li><strong>開発言語</strong>: Kotlin 2.x, Rust (2021 Edition)</li><li><strong>UI フレームワーク</strong>: Jetpack Compose (Compose BOM <code>2026.06.01</code>)</li><li><strong>デザインシステム</strong>: Miuix KMP (<code>0.9.3</code>)</li><li><strong>非同期処理</strong>: Kotlin Coroutines &amp; StateFlow (<code>1.11.0</code>)</li><li><strong>画面遷移</strong>: AndroidX Navigation 3 (<code>1.1.4</code>)</li></ul><h3 id="ネットワーク-画像処理" tabindex="-1">ネットワーク &amp; 画像処理 <a class="header-anchor" href="#ネットワーク-画像処理" aria-label="Permalink to &quot;ネットワーク &amp; 画像処理&quot;">​</a></h3><ul><li><strong>API 通信コア</strong>: Rust クレート (<code>pixiv-api</code>) + UniFFI JNI バインディング</li><li><strong>HTTP トランスポート</strong>: OkHttp (<code>5.4.0</code>)</li><li><strong>画像読み込み・キャッシュ</strong>: Coil 3 (<code>3.5.0</code>) - GIF / Zip / ネットワークキャッシュ対応</li><li><strong>Web 認証</strong>: AndroidX Browser Custom Tabs (<code>1.10.0</code>)</li></ul><h3 id="ローカルデータ-セキュリティ" tabindex="-1">ローカルデータ &amp; セキュリティ <a class="header-anchor" href="#ローカルデータ-セキュリティ" aria-label="Permalink to &quot;ローカルデータ &amp; セキュリティ&quot;">​</a></h3><ul><li><strong>データベース</strong>: Room (<code>2.8.4</code>)</li><li><strong>設定データストア</strong>: Jetpack DataStore Preferences (<code>1.2.1</code>)</li><li><strong>暗号化</strong>: AndroidX Security Crypto (<code>1.1.0</code>) + KeyStore (AES-256-GCM)</li><li><strong>生体認証</strong>: AndroidX Biometric (<code>1.4.0-alpha07</code>)</li></ul><hr><h2 id="主な機能一覧" tabindex="-1">主な機能一覧 <a class="header-anchor" href="#主な機能一覧" aria-label="Permalink to &quot;主な機能一覧&quot;">​</a></h2><h3 id="_1-作品閲覧-リーダー" tabindex="-1">1. 作品閲覧 &amp; リーダー <a class="header-anchor" href="#_1-作品閲覧-リーダー" aria-label="Permalink to &quot;1. 作品閲覧 &amp; リーダー&quot;">​</a></h3><ul><li><strong>イラスト・マンガ</strong>: ピンチズーム、複数ページ一覧/見開き表示、各種画質切り替え。</li><li><strong>うごイラ</strong>: Zip フレームデータの非同期ダウンロード、デコード、再生速度・ループ制御。</li><li><strong>小説</strong>: 縦書き/横書き表示切り替え、フォント・行間・テーマ変更、インライン挿絵表示。</li><li><strong>ショートフィード</strong>: フルスクリーンでの縦スワイプ作品観賞。</li></ul><h3 id="_2-高度な検索-ウォッチリスト" tabindex="-1">2. 高度な検索 &amp; ウォッチリスト <a class="header-anchor" href="#_2-高度な検索-ウォッチリスト" aria-label="Permalink to &quot;2. 高度な検索 &amp; ウォッチリスト&quot;">​</a></h3><ul><li>タグ部分一致 / 完全一致、作品タイトル・キャプション検索、ユーザー検索。</li><li>ブックマーク数フィルター（100 / 500 / 1000 / 5000 / 10000users 入り）。</li><li>お気に入りタグを管理するウォッチリスト（新着件数確認）。</li></ul><h3 id="_3-ダウンロードマネージャー" tabindex="-1">3. ダウンロードマネージャー <a class="header-anchor" href="#_3-ダウンロードマネージャー" aria-label="Permalink to &quot;3. ダウンロードマネージャー&quot;">​</a></h3><ul><li>原寸（オリジナル画質）画像の保存。</li><li>作者名・作品IDによるフォルダ自動分離。</li><li>1〜5 の並列ダウンロードキュー管理および自動ブックマーク連動。</li></ul><h3 id="_4-セキュリティ-カムフラージュ" tabindex="-1">4. セキュリティ &amp; カムフラージュ <a class="header-anchor" href="#_4-セキュリティ-カムフラージュ" aria-label="Permalink to &quot;4. セキュリティ &amp; カムフラージュ&quot;">​</a></h3><ul><li>PIN コードおよび生体認証（指紋/顔認証）によるアプリロック。</li><li>四則演算機能を備えた電卓偽装モード (<code>CalculatorEngine</code>)。</li><li><code>FLAG_SECURE</code> によるスクリーンショット防止とタスク一覧画面のマスキング。</li></ul><h3 id="_5-システム連携" tabindex="-1">5. システム連携 <a class="header-anchor" href="#_5-システム連携" aria-label="Permalink to &quot;5. システム連携&quot;">​</a></h3><ul><li>ブックマーク作品のローテーション表示を行うライブ壁紙サービス (<code>PalleriaLiveWallpaperService</code>)。</li><li>ホーム画面用ランキング表示および単体イラストウィジェット。</li></ul><hr><h2 id="動作要件" tabindex="-1">動作要件 <a class="header-anchor" href="#動作要件" aria-label="Permalink to &quot;動作要件&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">項目</th><th style="text-align:left;">条件 / 仕様</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>最小 OS</strong></td><td style="text-align:left;">Android 10 (API Level 29)</td></tr><tr><td style="text-align:left;"><strong>ターゲット SDK</strong></td><td style="text-align:left;">Android 14 (API Level 34)</td></tr><tr><td style="text-align:left;"><strong>対応 ABI</strong></td><td style="text-align:left;"><code>arm64-v8a</code>, <code>armeabi-v7a</code>, <code>x86_64</code></td></tr><tr><td style="text-align:left;"><strong>ライセンス</strong></td><td style="text-align:left;">GNU General Public License v3.0 (GPL-3.0-only)</td></tr></tbody></table><hr><h2 id="スクリーンショット" tabindex="-1">スクリーンショット <a class="header-anchor" href="#スクリーンショット" aria-label="Permalink to &quot;スクリーンショット&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">ホーム画面</th><th style="text-align:center;">検索画面</th><th style="text-align:center;">ランキング</th><th style="text-align:center;">ユーザープロフィール</th></tr></thead><tbody><tr><td style="text-align:center;"><img src="https://yunfi.f5.si/Palleria/repo/com.yunfie.illustia/en-US/phoneScreenshots/1.png" width="160" alt="Home"></td><td style="text-align:center;"><img src="https://yunfi.f5.si/Palleria/repo/com.yunfie.illustia/en-US/phoneScreenshots/2.png" width="160" alt="Search"></td><td style="text-align:center;"><img src="https://yunfi.f5.si/Palleria/repo/com.yunfie.illustia/en-US/phoneScreenshots/3.png" width="160" alt="Ranking"></td><td style="text-align:center;"><img src="https://yunfi.f5.si/Palleria/repo/com.yunfie.illustia/en-US/phoneScreenshots/5.png" width="160" alt="Profile"></td></tr></tbody></table>',31)])])}const p=e(r,[["render",o]]);export{u as __pageData,p as default};
